/* Spotify Theme - Official Spotify brand colors */

/* Light mode */
[data-theme="spotify-light"] {
  --background: hsl(300 50% 100%);
  --foreground: hsl(5.65 17.99% 5.5%);
  --card: hsl(345.04 22.05% 97.6%);
  --card-foreground: hsl(5.65 17.99% 5.5%);
  --popover: hsl(300 50% 100%);
  --popover-foreground: hsl(5.65 17.99% 5.5%);
  --primary: hsl(150.48 99.92% 32.9%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(132.2 15.14% 93.08%);
  --secondary-foreground: hsl(5.65 14.46% 9.04%);
  --muted: hsl(345.04 10.48% 94.98%);
  --muted-foreground: hsl(344.61 3.73% 39.48%);
  --accent: hsl(147.81 99.89% 38.67%);
  --accent-foreground: hsl(5.65 17.99% 5.5%);
  --destructive: hsl(351.89 92.21% 43.24%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(345.04 4.05% 87.21%);
  --input: hsl(345.04 5.09% 89.79%);
  --ring: hsl(150.48 99.92% 32.9%);
  --chart-1: hsl(150.48 99.92% 32.9%);
  --chart-2: hsl(147.81 99.89% 38.67%);
  --chart-3: hsl(182.4 99.88% 29.85%);
  --chart-4: hsl(236.37 65.1% 73.64%);
  --chart-5: hsl(317.12 57.92% 59.32%);
  --radius: 0.5rem;
  --sidebar: hsl(5.65 17.99% 5.5%);
  --sidebar-foreground: hsl(345.04 8.3% 93.68%);
  --sidebar-primary: hsl(150.48 99.92% 32.9%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(5.73 10.22% 13.61%);
  --sidebar-accent-foreground: hsl(345.04 8.3% 93.68%);
  --sidebar-border: hsl(5.77 8.72% 16.47%);
  --sidebar-ring: hsl(150.48 99.92% 32.9%);
  --font-sans: Montserrat, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, monospace;
  --shadow-color: hsl(150 60% 10%);
  --shadow-opacity: 0.08;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(150 60% 10% / 0.04);
  --shadow-xs: 0 1px 3px 0px hsl(150 60% 10% / 0.06);
  --shadow-sm: 0 2px 4px 0px hsl(150 60% 10% / 0.08), 0 1px 2px -1px hsl(150 60% 10% / 0.08);
  --shadow: 0 2px 4px 0px hsl(150 60% 10% / 0.08), 0 1px 2px -1px hsl(150 60% 10% / 0.08);
  --shadow-md: 0 4px 6px 0px hsl(150 60% 10% / 0.1), 0 2px 4px -1px hsl(150 60% 10% / 0.1);
  --shadow-lg: 0 8px 10px 0px hsl(150 60% 10% / 0.1), 0 4px 6px -1px hsl(150 60% 10% / 0.1);
  --shadow-xl: 0 16px 20px 0px hsl(150 60% 10% / 0.12), 0 8px 10px -1px hsl(150 60% 10% / 0.12);
  --shadow-2xl: 0 24px 48px 0px hsl(150 60% 10% / 0.2);
  --tracking-normal: -0.01em;
}

/* Dark mode - #121212 is Spotify's signature dark background */
[data-theme="spotify-dark"] {
  --background: hsl(300 0% 3.94%);
  --foreground: hsl(300 50% 100%);
  --card: hsl(0 0% 6.87%);
  --card-foreground: hsl(300 50% 100%);
  --popover: hsl(0 0% 8.61%);
  --popover-foreground: hsl(300 50% 100%);
  --primary: hsl(150.48 99.92% 32.9%);
  --primary-foreground: hsl(300 0% 3.94%);
  --secondary: hsl(300 0% 10.4%);
  --secondary-foreground: hsl(300 0% 86.98%);
  --muted: hsl(0 0% 8.61%);
  --muted-foreground: hsl(330 0% 56.07%);
  --accent: hsl(147.81 99.89% 38.67%);
  --accent-foreground: hsl(300 0% 3.94%);
  --destructive: hsl(359.22 71.52% 55.23%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(0 0% 15.99%);
  --input: hsl(300 0% 10.4%);
  --ring: hsl(150.48 99.92% 32.9%);
  --chart-1: hsl(150.48 99.92% 32.9%);
  --chart-2: hsl(147.81 99.89% 38.67%);
  --chart-3: hsl(182.38 99.99% 33.26%);
  --chart-4: hsl(236.06 87.35% 79.93%);
  --chart-5: hsl(318.18 61.84% 65.96%);
  --radius: 0.5rem;
  --sidebar: hsl(330 0% 2.23%);
  --sidebar-foreground: hsl(300 50% 100%);
  --sidebar-primary: hsl(150.48 99.92% 32.9%);
  --sidebar-primary-foreground: hsl(300 0% 3.94%);
  --sidebar-accent: hsl(300 0% 10.4%);
  --sidebar-accent-foreground: hsl(300 0% 86.98%);
  --sidebar-border: hsl(0 0% 15.99%);
  --sidebar-ring: hsl(150.48 99.92% 32.9%);
  --font-sans: Montserrat, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, monospace;
  --shadow-color: hsl(0 0% 0%);
  --shadow-opacity: 0.5;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(0 0% 0% / 0.25);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.35);
  --shadow-sm: 0 2px 4px 0px hsl(0 0% 0% / 0.5), 0 1px 2px -1px hsl(0 0% 0% / 0.5);
  --shadow: 0 2px 4px 0px hsl(0 0% 0% / 0.5), 0 1px 2px -1px hsl(0 0% 0% / 0.5);
  --shadow-md: 0 4px 6px 0px hsl(0 0% 0% / 0.5), 0 2px 4px -1px hsl(0 0% 0% / 0.5);
  --shadow-lg: 0 8px 10px 0px hsl(0 0% 0% / 0.5), 0 4px 6px -1px hsl(0 0% 0% / 0.5);
  --shadow-xl: 0 16px 20px 0px hsl(0 0% 0% / 0.5), 0 8px 10px -1px hsl(0 0% 0% / 0.5);
  --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.6);
}
